from kinex import device
from tube_transfer_checked import move,capture
try:
 s=device('right_gripper');last=s['timestamp']
 if s['faults']:raise RuntimeError(s['faults'])
 r=device('right_gripper','write',{'actions':[0.0],'duration_s':2})
 for _ in range(35):
  device('world','wait',{'duration_s':.2});s=device('right_gripper')
  if s['faults'] or s['timestamp']<=last or s.get('controller',{}).get('execution_id')!=r['execution_id']:raise RuntimeError(s)
  last=s['timestamp']
  if s['controller']['completed']:break
 else:raise RuntimeError('grip completion timeout')
 print(s)
 move('right_arm',delta=[0,0,.015],speed=.07,linear_speed=.006)
except Exception:
 device('right_arm','stop');raise
capture(['right_wrist_stereo','left_wrist_stereo'])

